import{_ as a,o as t,c as r,ag as i}from"./chunks/framework.DMXcdKmJ.js";const f=JSON.parse('{"title":"使用指南目录","description":"按工程管理、应用开发、数据中心等模块查找对应操作，不混淆组织账号与工程身份。","frontmatter":{"title":"使用指南目录","description":"按工程管理、应用开发、数据中心等模块查找对应操作，不混淆组织账号与工程身份。","status":"reviewed","kind":"navigation"},"headers":[],"relativePath":"zh/guide/index.md","filePath":"zh/使用指南/使用指南目录.md"}'),d={name:"zh/guide/index.md"};function o(h,e,l,s,n,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="使用指南目录" tabindex="-1">使用指南目录 <a class="header-anchor" href="#使用指南目录" aria-label="Permalink to &quot;使用指南目录&quot;">​</a></h1><p>使用指南按平台模块分层组织。展开左侧模块，再选择具体任务；手机上先打开“目录”。新手可先完成<a href="/induframe-docs/zh/start/first-project.html">创建第一个工程</a>。</p><h2 id="账号与组织" tabindex="-1">账号与组织 <a class="header-anchor" href="#账号与组织" aria-label="Permalink to &quot;账号与组织&quot;">​</a></h2><ul><li><a href="/induframe-docs/zh/guide/login.html">登录与退出</a>：进入正确的组织和工作台。</li><li><a href="/induframe-docs/zh/guide/organizations.html">管理组织</a>：平台超级管理员维护组织。</li><li><a href="/induframe-docs/zh/guide/users.html">添加和管理组织用户</a>：组织管理员分配工作台账号。</li></ul><h2 id="工程管理" tabindex="-1">工程管理 <a class="header-anchor" href="#工程管理" aria-label="Permalink to &quot;工程管理&quot;">​</a></h2><p><a href="/induframe-docs/zh/guide/projects.html">创建和管理工程</a>：新建、查找、整理、共享、导入导出与删除工程。</p><h2 id="工程用户与角色" tabindex="-1">工程用户与角色 <a class="header-anchor" href="#工程用户与角色" aria-label="Permalink to &quot;工程用户与角色&quot;">​</a></h2><ul><li><a href="/induframe-docs/zh/guide/project-users.html">管理工程用户</a>：维护工程页面的初始登录用户。</li><li><a href="/induframe-docs/zh/guide/project-roles.html">管理工程角色</a>：建立角色、绑定用户，并明确可调用数据点的范围。</li></ul><p>这些是工程身份预设，不是组织工作台账号；正式运行需要随工程发布、更新安排同步。</p><h2 id="应用开发" tabindex="-1">应用开发 <a class="header-anchor" href="#应用开发" aria-label="Permalink to &quot;应用开发&quot;">​</a></h2><p>先看<a href="/induframe-docs/zh/guide/workspace.html">工作区入门</a>，再按工作区区域选择：</p><ul><li><strong>AI 开发区域</strong>：<a href="/induframe-docs/zh/guide/ai-development.html">助手开发</a>、<a href="/induframe-docs/zh/guide/ai-models.html">模型配置</a>、<a href="/induframe-docs/zh/guide/ai-skills.html">工程技能</a>。</li><li><strong>AI 创建的配置在哪里</strong>：<a href="/induframe-docs/zh/guide/ai-data-review.html">按查询、数据点、计算和报警逐项核对</a>。</li><li><strong>页面预览</strong>：<a href="/induframe-docs/zh/guide/preview.html">预览页面、切换身份与独立窗口</a>。</li><li><strong>代码编辑器</strong>：<a href="/induframe-docs/zh/guide/code-editor.html">修改源码、保存和与 AI 协作</a>。</li><li><strong>对象存储管理</strong>：<a href="/induframe-docs/zh/guide/project-files.html">上传、打开、替换与移除工程资源</a>。</li><li><strong>数据点管理</strong>：<a href="/induframe-docs/zh/guide/workspace-datapoints.html">选点、复制路径和配置工程角色调用权限</a>。</li></ul><p>源码文件、工程对象库文件与开发预览是不同用途，不要把对话完成或资源上传当成正式发布。</p><h2 id="数据中心" tabindex="-1">数据中心 <a class="header-anchor" href="#数据中心" aria-label="Permalink to &quot;数据中心&quot;">​</a></h2><p>先看<a href="/induframe-docs/zh/guide/datacenter.html">数据中心入门</a>。</p><ul><li><strong>数据点列表</strong>：<a href="/induframe-docs/zh/guide/datapoints.html">查看来源、当前值、标签和失效项</a>。</li><li><strong>接入源</strong>：<a href="/induframe-docs/zh/guide/access-sources.html">连接管理</a>、<a href="/induframe-docs/zh/guide/builtin-stores.html">内置库</a>、<a href="/induframe-docs/zh/guide/mysql.html">MySQL</a>、<a href="/induframe-docs/zh/guide/postgresql.html">PostgreSQL</a>、<a href="/induframe-docs/zh/guide/sqlserver.html">SQL Server</a>。</li><li><strong>SQL 查询与数据点</strong>：<a href="/induframe-docs/zh/guide/sql-datapoints.html">运行、保存、提取字段并生成点</a>。</li><li><strong>工业采集</strong>：<a href="/induframe-docs/zh/guide/industrial-connections.html">配置连接、变量与节点验证</a>。</li></ul><h2 id="运维管理" tabindex="-1">运维管理 <a class="header-anchor" href="#运维管理" aria-label="Permalink to &quot;运维管理&quot;">​</a></h2><p>从<a href="/induframe-docs/zh/guide/operations.html">运维入门</a>认识运行任务，再选择子模块：</p><ul><li><strong>运行环境</strong>：<a href="/induframe-docs/zh/guide/runtime-environments.html">创建环境、关联节点与准备基础服务</a>。</li><li><strong>节点管理</strong>：<a href="/induframe-docs/zh/guide/runtime-nodes.html">接入、核对资格与环境归属</a>。</li><li><strong>工程部署</strong>：<a href="/induframe-docs/zh/guide/deployments.html">模式、版本、节点、访问入口和启停</a>。</li><li><strong>运维记录</strong>：<a href="/induframe-docs/zh/guide/operations-records.html">操作进度、系统事件和执行明细</a>。</li></ul><h2 id="分清容易混淆的入口" tabindex="-1">分清容易混淆的入口 <a class="header-anchor" href="#分清容易混淆的入口" aria-label="Permalink to &quot;分清容易混淆的入口&quot;">​</a></h2><p>先核对入口用途，避免在错误模块重复添加配置。</p><table tabindex="0"><thead><tr><th>名称</th><th>用途</th></tr></thead><tbody><tr><td>组织用户</td><td>登录组织工作台，管理或开发有权限的工程</td></tr><tr><td>工程用户与角色</td><td>工程页面自己的身份和数据访问范围，不等于组织账号</td></tr><tr><td>应用开发</td><td>维护源码、页面和开发资料</td></tr><tr><td>数据中心</td><td>配置工程数据、来源、采集、计算和报警</td></tr><tr><td>运维管理</td><td>管理运行环境、节点、部署和运行记录，与开发预览分开</td></tr></tbody></table><p>其他模块随独立操作指南完成后加入对应层级，不提供无法点击的占位入口。正式运行的概念见<a href="/induframe-docs/zh/concepts/development-and-runtime.html">开发、发布与运行</a>。</p>',23)])])}const c=a(d,[["render",o]]);export{f as __pageData,c as default};
